// Every node kind, then the three states, drawn with wb.node.
const column = (i) => 20 + i * 170;
const size = { width: 150, height: 64 };

const kinds = [
  ["person", "Reader"],
  ["system", "Orders"],
  ["container", "API", "Container · Node.js"],
  ["component", "Read path"],
  ["database", "Postgres"],
  ["queue", "Order events", "Queue · Kafka"],
  ["external", "Stripe"],
];

kinds.forEach(([kind, label, tag], i) =>
  wb.node({ kind, label, tag, x: column(i % 4), y: i < 4 ? 36 : 152, ...size }),
);

const states = [
  ["container", "API", "default"],
  ["container", "API", "active"],
  ["container", "API", "dimmed"],
  ["database", "Postgres", "active"],
];

states.forEach(([kind, label, state], i) =>
  wb.node({ kind, label, tag: state, state, x: column(i), y: 284, ...size }),
);
